// Writes nodes/Scavio/version.ts from package.json so the User-Agent sent on
// every API call always matches the published version. Runs before tsc in
// `npm run build`.
const fs = require('fs');
const path = require('path');

const root = path.join(__dirname, '..');
const { version } = JSON.parse(fs.readFileSync(path.join(root, 'package.json'), 'utf8'));
const out = path.join(root, 'nodes', 'Scavio', 'version.ts');
const body =
	'// Generated by scripts/gen-version.js from package.json. Do not edit.\n' +
	`export const NODE_PACKAGE_VERSION = '${version}';\n`;
if (!fs.existsSync(out) || fs.readFileSync(out, 'utf8') !== body) {
	fs.writeFileSync(out, body);
}
